    artifact: &AcceptedArtifact,
) -> Result<CompiledWorkflow, JournalError> {
    let len = u32::try_from(artifact.ir.len()).map_err(|_| JournalError::ArtifactMalformed)?;
    if len > crate::constants::MAX_COMPILED_IR_BYTES {
